const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");
const fs = require("fs");

// Icon imports
const { FaBrain, FaBalanceScale, FaRulerVertical, FaBolt, FaTrophy, FaChartBar, FaCogs, FaLightbulb, FaArrowRight, FaCheckCircle, FaExclamationTriangle, FaCrosshairs, FaLayerGroup, FaSlidersH, FaCut, FaCoins, FaUsers, FaRocket, FaStar } = require("react-icons/fa");
const { MdTimeline, MdTrendingUp, MdInsights } = require("react-icons/md");

// ─── Color Palette: Deep Tech / Midnight ───
const C = {
  bg:         "0F1629",   // deep midnight
  bgCard:     "1A2240",   // card background
  bgCardAlt:  "232B4A",   // alternate card
  accent:     "4FC3F7",   // bright cyan
  accentDark: "0288D1",   // darker cyan
  green:      "00E676",   // success green
  greenDark:  "00C853",
  orange:     "FFB74D",   // warning orange
  red:        "FF5252",   // alert red
  purple:     "B388FF",   // purple accent
  textWhite:  "ECEFF1",   // primary text
  textMuted:  "8892B0",   // muted text
  textDim:    "546E7A",   // dim text
  divider:    "2A3258",   // subtle divider
  chartBg:    "141B30",
};

// Font config
const FONT_HEAD = "Trebuchet MS";
const FONT_BODY = "Calibri";

// ─── Icon helper ───
function renderIconSvg(IconComponent, color, size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}
async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Helper: fresh shadow objects (PptxGenJS mutates)
const mkShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 });
const mkSoftShadow = () => ({ type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.15 });

async function buildDeck() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "VAPO Research Team";
  pres.title = "VAPO: Value-Model-Based RL for Advanced Reasoning";

  // ════════════════════════════════════════════════════════
  // SLIDE 1: Title Slide
  // ════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg };

    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent }
    });

    // Large hero number
    slide.addText("60.4", {
      x: 6.2, y: 0.8, w: 3.5, h: 2.2,
      fontSize: 96, fontFace: FONT_HEAD, color: C.accent, bold: true, align: "right",
      margin: 0, transparency: 15
    });
    slide.addText("AIME 2024", {
      x: 6.2, y: 2.7, w: 3.5, h: 0.5,
      fontSize: 16, fontFace: FONT_BODY, color: C.textMuted, align: "right", margin: 0
    });

    // Title
    slide.addText("VAPO", {
      x: 0.7, y: 1.0, w: 6, h: 0.8,
      fontSize: 44, fontFace: FONT_HEAD, color: C.textWhite, bold: true, margin: 0
    });
    slide.addText("Value-Model-Based Reinforcement Learning\nfor Advanced Reasoning", {
      x: 0.7, y: 1.85, w: 5.5, h: 0.85,
      fontSize: 18, fontFace: FONT_BODY, color: C.textMuted, margin: 0, lineSpacingMultiple: 1.3
    });

    // Divider line
    slide.addShape(pres.shapes.LINE, {
      x: 0.7, y: 3.05, w: 3.5, h: 0, line: { color: C.accent, width: 2 }
    });

    // Key result callout
    slide.addText([
      { text: "Surpassing DAPO by 10+ points on AIME 2024", options: { fontSize: 14, color: C.textWhite, bold: true } }
    ], { x: 0.7, y: 3.35, w: 5.5, h: 0.4, fontFace: FONT_BODY, margin: 0 });

    // Footer info
    slide.addText("ByteDance Seed  |  Base Model: Qwen2.5-32B  |  No SFT Data", {
      x: 0.7, y: 4.8, w: 6, h: 0.35,
      fontSize: 11, fontFace: FONT_BODY, color: C.textDim, margin: 0
    });
    slide.addText("arxiv.org/abs/2504.05118", {
      x: 0.7, y: 5.1, w: 3, h: 0.3,
      fontSize: 10, fontFace: FONT_BODY, color: C.textDim, margin: 0, italic: true
    });
  }

  // ════════════════════════════════════════════════════════
  // SLIDE 2: Motivation — Why Value Models?
  // ════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg };

    // Title
    slide.addText("Why Value Models?", {
      x: 0.7, y: 0.4, w: 8, h: 0.6,
      fontSize: 36, fontFace: FONT_HEAD, color: C.textWhite, bold: true, margin: 0
    });
    slide.addText("Finer Credit Assignment for Long Chain-of-Thought Reasoning", {
      x: 0.7, y: 1.0, w: 8, h: 0.4,
      fontSize: 14, fontFace: FONT_BODY, color: C.textMuted, margin: 0
    });

    // Two-column comparison
    const colW = 4.0;
    const colY = 1.7;
    const colH = 3.3;

    // Left column: Value-Free
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: colY, w: colW, h: colH,
      fill: { color: C.bgCard }, shadow: mkShadow()
    });
    // Left accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: colY, w: 0.06, h: colH,
      fill: { color: C.orange }
    });
    slide.addText("VALUE-FREE METHODS", {
      x: 1.05, y: colY + 0.2, w: colW - 0.55, h: 0.35,
      fontSize: 13, fontFace: FONT_HEAD, color: C.orange, bold: true, margin: 0, charSpacing: 2
    });
    slide.addText("GRPO, DAPO", {
      x: 1.05, y: colY + 0.55, w: colW - 0.55, h: 0.3,
      fontSize: 11, fontFace: FONT_BODY, color: C.textDim, margin: 0
    });
    slide.addText([
      { text: "Trajectory-level advantage", options: { bullet: true, breakLine: true, fontSize: 13, color: C.textWhite } },
      { text: "Uniform credit across all tokens", options: { bullet: true, breakLine: true, fontSize: 13, color: C.textWhite } },
      { text: "Monte Carlo estimates (high variance)", options: { bullet: true, breakLine: true, fontSize: 13, color: C.textWhite } },
      { text: "No per-token signal for subtle errors", options: { bullet: true, fontSize: 13, color: C.textWhite } }
    ], { x: 1.05, y: colY + 1.0, w: colW - 0.55, h: 2.0, fontFace: FONT_BODY, margin: 0, paraSpaceAfter: 8 });

    // Right column: Value-Based
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: colY, w: colW, h: colH,
      fill: { color: C.bgCard }, shadow: mkShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: colY, w: 0.06, h: colH,
      fill: { color: C.green }
    });
    slide.addText("VALUE-BASED METHODS", {
      x: 5.65, y: colY + 0.2, w: colW - 0.55, h: 0.35,
      fontSize: 13, fontFace: FONT_HEAD, color: C.green, bold: true, margin: 0, charSpacing: 2
    });
    slide.addText("PPO with Value Model (VAPO)", {
      x: 5.65, y: colY + 0.55, w: colW - 0.55, h: 0.3,
      fontSize: 11, fontFace: FONT_BODY, color: C.textDim, margin: 0
    });
    slide.addText([
      { text: "Token-level credit assignment", options: { bullet: true, breakLine: true, fontSize: 13, color: C.textWhite } },
      { text: "Traces each action's impact on returns", options: { bullet: true, breakLine: true, fontSize: 13, color: C.textWhite } },
      { text: "Lower-variance estimates per token", options: { bullet: true, breakLine: true, fontSize: 13, color: C.textWhite } },
      { text: "Generalizes across samples", options: { bullet: true, fontSize: 13, color: C.textWhite } }
    ], { x: 5.65, y: colY + 1.0, w: colW - 0.55, h: 2.0, fontFace: FONT_BODY, margin: 0, paraSpaceAfter: 8 });

    // Arrow between columns
    const arrowIcon = await iconToBase64Png(FaArrowRight, `#${C.accent}`, 256);
    slide.addImage({ data: arrowIcon, x: 4.75, y: colY + 1.3, w: 0.5, h: 0.5 });

    // Bottom note
    slide.addText("Critical for multi-step reasoning where subtle step-level errors cause catastrophic failures.", {
      x: 0.7, y: 5.15, w: 8.5, h: 0.35,
      fontSize: 11, fontFace: FONT_BODY, color: C.textDim, italic: true, margin: 0
    });
