      fontSize: 16, fontFace: FONT_BODY, color: C.green, bold: true, margin: 0
    });

    slide.addText([
      { text: "Lower bias estimates", options: { bullet: true, breakLine: true, fontSize: 12, color: C.textWhite } },
      { text: "Combats compounding errors", options: { bullet: true, breakLine: true, fontSize: 12, color: C.textWhite } },
      { text: "Better for long reasoning chains", options: { bullet: true, fontSize: 12, color: C.textWhite } }
    ], { x: 5.55, y: panelY + 1.3, w: 3.5, h: 1.1, fontFace: FONT_BODY, margin: 0, paraSpaceAfter: 6 });

    // Key insight box at bottom
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 4.55, w: 8.6, h: 0.85,
      fill: { color: C.bgCard }, shadow: mkSoftShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 4.55, w: 0.05, h: 0.85,
      fill: { color: C.accent }
    });
    const insightIcon = await iconToBase64Png(FaLightbulb, `#${C.accent}`, 256);
    slide.addImage({ data: insightIcon, x: 0.95, y: 4.72, w: 0.35, h: 0.35 });
    slide.addText("Addresses the heterogeneous sequence length problem unique to long-CoT reasoning. Contributes 15 points in ablation (45 → 60).", {
      x: 1.45, y: 4.55, w: 7.6, h: 0.85,
      fontSize: 12, fontFace: FONT_BODY, color: C.textWhite, valign: "middle", margin: 0
    });
  }

  // ════════════════════════════════════════════════════════
  // SLIDE 6: Main Results — Bar Chart
  // ════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg };

    slide.addText("AIME 2024 Results: VAPO Scores 60", {
      x: 0.7, y: 0.35, w: 8.6, h: 0.55,
      fontSize: 32, fontFace: FONT_HEAD, color: C.textWhite, bold: true, margin: 0
    });
    slide.addText("10+ points above DAPO and DeepSeek-R1-Zero  |  avg@32  |  Qwen2.5-32B base, no SFT", {
      x: 0.7, y: 0.9, w: 8.6, h: 0.35,
      fontSize: 12, fontFace: FONT_BODY, color: C.textMuted, margin: 0
    });

    // Bar chart
    slide.addChart(pres.charts.BAR, [{
      name: "AIME 2024 (avg@32)",
      labels: ["Vanilla PPO", "DeepSeek-R1-Zero\nQwen-32B", "DAPO", "VAPO"],
      values: [5, 47, 50, 60]
    }], {
      x: 0.5, y: 1.45, w: 5.2, h: 3.8,
      barDir: "col",
      chartColors: [C.textDim, C.orange, C.orange, C.accent],
      bar3DShape: "box",
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: C.textWhite,
      dataLabelFontSize: 14,
      dataLabelFontBold: true,
      catAxisLabelColor: C.textMuted,
      catAxisLabelFontSize: 10,
      valAxisLabelColor: C.textDim,
      valAxisLabelFontSize: 9,
      valGridLine: { color: C.divider, size: 0.5 },
      catGridLine: { style: "none" },
      showLegend: false,
      chartArea: { fill: { color: C.chartBg }, roundedCorners: true },
      valAxisMaxVal: 70,
    });

    // Right side: key stats
    const statsX = 6.1;
    const statsW = 3.5;

    slide.addShape(pres.shapes.RECTANGLE, {
      x: statsX, y: 1.45, w: statsW, h: 1.5,
      fill: { color: C.bgCard }, shadow: mkSoftShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: statsX, y: 1.45, w: 0.05, h: 1.5,
      fill: { color: C.green }
    });
    slide.addText("+10.4", {
      x: statsX + 0.2, y: 1.55, w: 1.5, h: 0.6,
      fontSize: 36, fontFace: FONT_HEAD, color: C.green, bold: true, margin: 0
    });
    slide.addText("pts over DAPO", {
      x: statsX + 1.7, y: 1.65, w: 1.5, h: 0.4,
      fontSize: 13, fontFace: FONT_BODY, color: C.textMuted, margin: 0
    });
    slide.addText("+13.4 pts over DeepSeek-R1-Zero-Qwen-32B", {
      x: statsX + 0.2, y: 2.25, w: 3.0, h: 0.4,
      fontSize: 11, fontFace: FONT_BODY, color: C.textMuted, margin: 0
    });

    // Training curve reference
    slide.addShape(pres.shapes.RECTANGLE, {
      x: statsX, y: 3.2, w: statsW, h: 2.1,
      fill: { color: C.bgCard }, shadow: mkSoftShadow()
    });
    slide.addText("TRAINING CURVE", {
      x: statsX + 0.15, y: 3.3, w: 3.2, h: 0.3,
