      fontSize: 13, fontFace: FONT_BODY, color: C.textMuted, margin: 0
    });

    // Left: Training curve (figure_2.jpg)
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: 1.55, w: 4.5, h: 3.6,
      fill: { color: C.bgCard }, shadow: mkShadow()
    });
    slide.addText("ACCURACY OVER TRAINING STEPS", {
      x: 0.7, y: 1.65, w: 4, h: 0.3,
      fontSize: 10, fontFace: FONT_HEAD, color: C.accent, bold: true, margin: 0, charSpacing: 1.5
    });
    slide.addImage({
      path: path.resolve("/app/benchmark/assets/figure_2.jpg"),
      x: 0.65, y: 2.05, w: 4.2, h: 2.9,
      sizing: { type: "contain", w: 4.2, h: 2.9 }
    });

    // Right: Response length (figure_3.jpg)
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: 1.55, w: 4.5, h: 3.6,
      fill: { color: C.bgCard }, shadow: mkShadow()
    });
    slide.addText("MEAN RESPONSE LENGTH OVER TRAINING", {
      x: 5.5, y: 1.65, w: 4.1, h: 0.3,
      fontSize: 10, fontFace: FONT_HEAD, color: C.green, bold: true, margin: 0, charSpacing: 1.5
    });
    slide.addImage({
      path: path.resolve("/app/benchmark/assets/figure_3.jpg"),
      x: 5.45, y: 2.05, w: 4.2, h: 2.9,
      sizing: { type: "contain", w: 4.2, h: 2.9 }
    });

    // Key callouts at bottom
    const callouts = [
      { stat: "~5K", label: "steps to SOTA", color: C.accent },
      { stat: "60%", label: "accuracy @ step 4,500", color: C.green },
      { stat: "0", label: "training crashes", color: C.green },
      { stat: "~6K", label: "tokens (longer reasoning)", color: C.orange }
    ];
    const callW = 2.05;
    for (let i = 0; i < 4; i++) {
      const cx = 0.5 + i * (callW + 0.2);
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: 5.25, w: callW, h: 0.0,
        fill: { color: C.bgCard }
      });
      slide.addText(callouts[i].stat, {
        x: cx, y: 5.0, w: callW * 0.45, h: 0.4,
        fontSize: 20, fontFace: FONT_HEAD, color: callouts[i].color, bold: true, margin: 0, align: "center"
      });
      slide.addText(callouts[i].label, {
        x: cx + callW * 0.45, y: 5.03, w: callW * 0.55, h: 0.35,
        fontSize: 10, fontFace: FONT_BODY, color: C.textMuted, margin: 0, valign: "middle"
      });
    }
  }

  // ════════════════════════════════════════════════════════
  // SLIDE 8: Ablation Study
  // ════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg };

    slide.addText("Ablation: Every Component Matters", {
      x: 0.7, y: 0.35, w: 8, h: 0.55,
      fontSize: 32, fontFace: FONT_HEAD, color: C.textWhite, bold: true, margin: 0
    });
    slide.addText("Value-Pretraining alone adds 49 points (11 → 60)", {
      x: 0.7, y: 0.9, w: 8, h: 0.35,
      fontSize: 13, fontFace: FONT_BODY, color: C.textMuted, margin: 0
    });

    // Ablation data sorted by contribution (largest drop first)
    const ablation = [
      { name: "Full VAPO", score: 60, drop: 0, isBase: true },
      { name: "w/o Value-Pretraining", score: 11, drop: 49 },
      { name: "w/o Decoupled-GAE", score: 33, drop: 27 },
      { name: "w/o Length-Adaptive GAE", score: 45, drop: 15 },
      { name: "w/o Clip-Higher", score: 46, drop: 14 },
      { name: "w/o Token-level Loss", score: 53, drop: 7 },
      { name: "w/o Positive Example LM Loss", score: 54, drop: 6 },
      { name: "w/o Group-Sampling", score: 55, drop: 5 }
    ];

    // Table-style layout with horizontal bars showing score
    const tableX = 0.7;
    const tableY = 1.55;
    const rowH = 0.48;
    const nameW = 3.2;
    const scoreW = 0.7;
    const barMaxW = 4.8;
    const barX = tableX + nameW + scoreW + 0.2;

    for (let i = 0; i < ablation.length; i++) {
      const ry = tableY + i * (rowH + 0.04);
      const item = ablation[i];
      const barW = (item.score / 65) * barMaxW;

      // Row background
      slide.addShape(pres.shapes.RECTANGLE, {
        x: tableX, y: ry, w: nameW + scoreW + 0.2 + barMaxW + 0.6, h: rowH,
        fill: { color: i === 0 ? C.bgCardAlt : C.bgCard }
      });

      // Component name
      slide.addText(item.name, {
        x: tableX + 0.15, y: ry, w: nameW - 0.15, h: rowH,
        fontSize: 11, fontFace: item.isBase ? FONT_HEAD : FONT_BODY,
        color: item.isBase ? C.accent : C.textWhite,
        bold: item.isBase, valign: "middle", margin: 0
      });

      // Score value
      slide.addText(String(item.score), {
        x: tableX + nameW, y: ry, w: scoreW, h: rowH,
        fontSize: 13, fontFace: FONT_HEAD, color: item.isBase ? C.accent : C.textWhite,
        bold: true, valign: "middle", align: "center", margin: 0
      });

      // Bar
      let barColor = C.accent;
      if (!item.isBase) {
        if (item.drop >= 25) barColor = C.red;
        else if (item.drop >= 10) barColor = C.orange;
        else barColor = C.textMuted;
      }
      slide.addShape(pres.shapes.RECTANGLE, {
        x: barX, y: ry + 0.1, w: barW, h: rowH - 0.2,
        fill: { color: barColor, transparency: item.isBase ? 0 : 20 }
      });

      // Drop annotation
      if (!item.isBase) {
        slide.addText(`−${item.drop}`, {
          x: barX + barW + 0.1, y: ry, w: 0.5, h: rowH,
          fontSize: 10, fontFace: FONT_BODY, color: barColor, valign: "middle", margin: 0, bold: true
        });
      }
    }

    // Callout box
    const boxY = tableY + ablation.length * (rowH + 0.04) + 0.15;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: boxY, w: 8.6, h: 0.55,
      fill: { color: C.red, transparency: 88 }
    });
    slide.addText("Critical finding: Without Value-Pretraining, value-model-based RL barely functions (score: 11 vs 60).", {
      x: 0.9, y: boxY, w: 8.2, h: 0.55,
      fontSize: 12, fontFace: FONT_BODY, color: C.red, valign: "middle", margin: 0, bold: true
    });
  }

  // ════════════════════════════════════════════════════════
  // SLIDE 9: Key Takeaways
  // ════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.bg };

    // Bottom accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 5.565, w: 10, h: 0.06, fill: { color: C.accent }
    });

    slide.addText("Key Takeaways", {
      x: 0.7, y: 0.35, w: 8, h: 0.6,
      fontSize: 36, fontFace: FONT_HEAD, color: C.textWhite, bold: true, margin: 0
    });
    slide.addText("Implications for Future Reasoning Model Development", {
      x: 0.7, y: 0.95, w: 8, h: 0.35,
      fontSize: 14, fontFace: FONT_BODY, color: C.textMuted, margin: 0
    });

    const takeaways = [
      {
        title: "Value-model-based RL can outperform value-free methods",
        desc: "VAPO achieves 60.4 on AIME 2024, surpassing DAPO (50) and DeepSeek-R1-Zero (47) — all on the same Qwen2.5-32B base model with no SFT data.",
        icon: FaTrophy, color: C.accent
      },
      {
        title: "Value-Pretraining is the single most impactful component",
        desc: "Contributing 49 points (11 → 60), it is the prerequisite for value-model-based RL to function in long-CoT settings.",
        icon: FaStar, color: C.green
      },
      {
        title: "Length-Adaptive GAE solves the heterogeneous length problem",
        desc: "A novel technique that dynamically adjusts the bias-variance tradeoff by response length, contributing 15 points.",
        icon: FaSlidersH, color: C.orange
      },
      {
        title: "Superior training efficiency and stability",
        desc: "Reaches SOTA in ~5,000 steps with zero training crashes across multiple runs, compared to DAPO's ~5,500 steps for a lower score.",
        icon: FaRocket, color: C.purple
      },
      {
        title: "The three core challenges must be addressed together",
        desc: "Bias, heterogeneous lengths, and reward sparsity each require targeted solutions — removing any major component causes severe degradation.",
        icon: FaCogs, color: C.accent
      }
    ];

    const cardX = 0.7;
    const cardW = 8.6;
    const cardH = 0.72;
    const startY = 1.55;
    const gap = 0.1;

    for (let i = 0; i < takeaways.length; i++) {
      const cy = startY + i * (cardH + gap);
      const tw = takeaways[i];

      // Card bg
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cardX, y: cy, w: cardW, h: cardH,
        fill: { color: C.bgCard }
      });
      // Left accent
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cardX, y: cy, w: 0.05, h: cardH,
        fill: { color: tw.color }
      });

      // Icon
      const iconData = await iconToBase64Png(tw.icon, `#${tw.color}`, 256);
      slide.addImage({ data: iconData, x: cardX + 0.2, y: cy + 0.17, w: 0.35, h: 0.35 });

      // Title
      slide.addText(tw.title, {
        x: cardX + 0.7, y: cy + 0.05, w: cardW - 1.0, h: 0.3,
        fontSize: 12, fontFace: FONT_HEAD, color: C.textWhite, bold: true, margin: 0
      });
      // Description
      slide.addText(tw.desc, {
        x: cardX + 0.7, y: cy + 0.35, w: cardW - 1.0, h: 0.32,
        fontSize: 10, fontFace: FONT_BODY, color: C.textMuted, margin: 0
      });
    }
  }

  // ─── Save ───
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Deck saved to /app/output/final_deck.pptx");
}

buildDeck().catch(err => { console.error(err); process.exit(1); });

